#include "ksPanelVersionTask.h"
#include <stdexcept>
#include <iostream>
#include <vector>
int main(){using T=ks::PanelVersionTask;using K=T::Kind;using S=T::Stage;using C=T::Child;unsigned cases=0;for(unsigned kind=0;kind<7;++kind)for(unsigned pair=0;pair<65536;++pair){T t(static_cast<K>(kind));unsigned clocks=0,reads=0;std::vector<C>children;while(t.stage()!=S::Complete){if(t.child()!=C::None){children.push_back(t.child());if(!t.resumeChild())throw std::runtime_error("child resume");continue;}auto cost=t.nextClocks();if(t.advanceBefore(cost-1,[](T::Read)->unsigned{throw std::runtime_error("early read");}))throw std::runtime_error("early budget");clocks+=t.advanceBefore(cost,[&](T::Read r){++reads;return r==T::Read::Source?0xff123456u:r==T::Read::Primary?pair&255:pair>>8;});}std::vector<C>expected=kind==1||kind==2?std::vector<C>{C::Label}:kind==4?std::vector<C>{C::Major,C::Dot,C::Minor}:kind==5?std::vector<C>{C::Version,C::PatchDot,C::PatchValue}:kind==6?std::vector<C>{C::PatchDot,C::PatchValue}:std::vector<C>{};if(children!=expected||clocks!=(kind==1||kind==2?46:kind==4?115:kind==5?81:kind==6?63:17)||reads!=(kind==4?3:kind>=5?1:0)||t.resumeChild())throw std::runtime_error("version children/lifecycle/clocks");if(kind==4&&(t.source()!=0xff123456u||t.primary()!=uint8_t(pair)||t.secondary()!=pair>>8||t.major()!=(pair&255)>>3||t.minor()!=(pair&7)))throw std::runtime_error("version fields");if(kind>=5&&t.patch()!=pair>>8)throw std::runtime_error("patch");++cases;}std::cout<<"PASS: "<<cases<<" pure panel-version properties\n";}
